package com.example;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Range;

@ConfigGroup("contrast")
public interface ContrastConfig extends Config
{
	@Range(min = 1, max = 200)
	@ConfigItem(
		keyName = "contrast",
		name = "Contrast",
		description = "100 = default. Above 100: darker darks + brighter brights. Below 100: flatter image."
	)
	default int contrast()
	{
		return 100;
	}
}

package com.example;

import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Image;
import java.awt.Point;
import java.awt.image.BufferedImage;
import java.awt.image.LookupOp;
import java.awt.image.ShortLookupTable;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

@Slf4j
public class ContrastOverlay extends Overlay
{
	private final ContrastConfig config;

	private BufferedImage processedFrame;
	private LookupOp cachedOp;
	private int lastContrastValue = -1;

	@Inject
	ContrastOverlay(ContrastConfig config)
	{
		this.config = config;
		setLayer(OverlayLayer.ALWAYS_ON_TOP);
		setPosition(OverlayPosition.DYNAMIC);
		setMovable(false);
		setPreferredLocation(new Point(0, 0));
	}

	void onNewFrame(Image image)
	{
		if (image == null || !(image instanceof BufferedImage))
		{
			return;
		}

		int contrastValue = config.contrast();
		if (contrastValue == 100)
		{
			return;
		}

		BufferedImage source = (BufferedImage) image;
		int w = source.getWidth();
		int h = source.getHeight();
		if (w <= 0 || h <= 0)
		{
			return;
		}

		if (contrastValue != lastContrastValue)
		{
			cachedOp = buildContrastOp(contrastValue);
			lastContrastValue = contrastValue;
		}

		if (processedFrame == null || processedFrame.getWidth() != w || processedFrame.getHeight() != h)
		{
			processedFrame = new BufferedImage(w, h, BufferedImage.TYPE_INT_RGB);
		}

		try
		{
			cachedOp.filter(source, processedFrame);
			Graphics2D g = source.createGraphics();
			g.drawImage(processedFrame, 0, 0, null);
			g.dispose();
		}
		catch (Exception e)
		{
			log.warn("contrast filter failed", e);
		}
	}

	void clearFrame()
	{
		processedFrame = null;
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		return null;
	}

	private LookupOp buildContrastOp(int sliderValue)
	{
		double strength = (sliderValue - 100.0) / 50.0;

		short[] curve = new short[256];
		for (int i = 0; i < 256; i++)
		{
			double x = (i - 128.0) / 128.0;
			double y;
			if (Math.abs(strength) < 0.001)
			{
				y = x;
			}
			else
			{
				double k = strength * 1.5;
				y = Math.tanh(x * k) / Math.tanh(k);
			}
			int out = (int) Math.round(y * 128.0 + 128.0);
			curve[i] = (short) Math.max(0, Math.min(255, out));
		}

		short[][] table = {curve, curve, curve};
		return new LookupOp(new ShortLookupTable(0, table), null);
	}
}

package com.example;

import com.google.inject.Provides;
import javax.inject.Inject;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.DrawManager;
import net.runelite.client.ui.overlay.OverlayManager;

@PluginDescriptor(
	name = "Contrast",
	description = "Adjusts the contrast of the game client",
	tags = {"contrast", "visual", "graphics"}
)
public class ContrastPlugin extends Plugin
{
	@Inject private DrawManager drawManager;
	@Inject private OverlayManager overlayManager;
	@Inject private ContrastOverlay overlay;

	private Runnable frameListener;

	@Override
	protected void startUp()
	{
		frameListener = () -> drawManager.requestNextFrameListener(overlay::onNewFrame);
		drawManager.registerEveryFrameListener(frameListener);
		overlayManager.add(overlay);
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(overlay);
		drawManager.unregisterEveryFrameListener(frameListener);
		overlay.clearFrame();
	}

	@Provides
	ContrastConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(ContrastConfig.class);
	}
}

package com.example;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class ContrastPluginTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(ContrastPlugin.class);
		RuneLite.main(args);
	}
}
